# Les espacements sont rétablis entre chiffres et mots, sans modifier les URL ni les identifiants HTML.
import re
def space_text(m):
 s=html.unescape(m.group(0))
 s=re.sub(r'(?<=[A-Za-zÀ-ÿ])(?=\d)', ' ',s)
 s=re.sub(r'(?<=\d)(?=[A-Za-zÀ-ÿ])',' ',s)
 s=re.sub(r'(?<=\w)(?=«)|(?<=»)(?=\w)',' ',s)
 s=s.replace('laB','la B').replace('uneHb','une Hb').replace('l’Hb','l’Hb').replace('duPROMPT','du PROMPT')
 s=re.sub(r'\bS (\d+)',r'S\1',s)
 s=re.sub(r'\bO (\d+\.\d+)',r'O\1',s)
 s=re.sub(r'\bB (12|9)\b',r'B\1',s)
 s=s.replace('B 12','B12').replace('HbA 1 c','HbA1c').replace('HbA 1c','HbA1c').replace('NRS 2002','NRS2002')
 s=re.sub(r'\b(\d+) ([bc])\b',r'\1\2',s)
 s=re.sub(r'(?<=[a-zà-ÿ])(?=[A-ZÀ-Ý]{2,}|B12|GLIM|NRS|HbA|DX)', ' ', s)
 return html.escape(s,quote=False)
out=re.sub(r'(?<=>)[^<]+(?=<)',space_text,out)
